/**
 * SVG 图标定义
 * SVG Icons Definitions
 */
class svgIcons
{
    /**
     * 获取 SVG 图标路径数据
     * Get SVG icon path data
     *
     * @param  string $name 图标名称
     * @return string|false SVG 路径数据，如果不存在返回 false
     */
    public static function getIcon($name)
    {
        $icons = self::getIcons();
        return isset($icons[$name]) ? $icons[$name] : false;
    }

    /**
     * 获取图标尺寸
     * Get icon size
     *
     * @param  string $name 图标名称
     * @return array|false 返回 [width, height]，如果不存在返回 false
     */
    public static function getIconSize($name)
    {
        $icon = self::getIcon($name);
        return $icon !== false && isset($icon['size']) ? $icon['size'] : false;
    }

